head.script:
	scwin.onpageload = function() {
		var c_cnt = 1;
		var c_subName = "sub";
		var c_xmlName = ".xml";
        var obj = {
            title : c_subName + 1,
            src : 'windowContainer_nameLayer_html_WESD-957_(WSQ-4921)_sub.xml',
            frameMode : "wframe",
            openAction : "existWindow"
        }
		//for (var i = 0; i < c_cnt; i++) {
			windowContainer1.createWindow(obj);
		//}

        var obj2 = {
            title : "<p>test</p>",
            src : 'windowContainer_nameLayer_html_WESD-957_(WSQ-4921)_sub.xml',
            frameMode : "wframe",
            openAction : "existWindow"
        }
        windowContainer1.createWindow(obj2);
	};

	scwin.onpageunload = function() {

	};

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.checkSimulate = function() {
		scwin.simulateWrapper('#windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow0', 'drag-n-drop', {
			dx: 150,
			dy: 0
		});
	}
	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('windowContainer1_name').children[1].innerText == 'sub1';
	} 
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow0').focus()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "scwin.checkSimulate()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
